  let guideLanguage;
  let guideStep = 0;
  let guideOpen = false;
  let pendingGuideInvite = '';
  const joinedRoomGuides = new Set();

  function showGuide() {
    const preferred = guideLanguage || readStorage(GUIDE_LANGUAGE_KEY) || readStorage(SITE_LANGUAGE_KEY);
    const browserLanguage = globalThis.navigator?.language || 'vi';
    const language = preferred === 'vi' || preferred === 'en'
      ? preferred : browserLanguage.toLowerCase().startsWith('vi') ? 'vi' : 'en';
    const guide = GUIDE_CONTENT[language];
    const step = guide.steps[guideStep];
    const last = guideStep === guide.steps.length - 1;
    const languageOptions = [['vi', 'Tiếng Việt'], ['en', 'English']].map(([code, label]) =>
      btn(label, 'guide-language', {
        tone: code === language ? 'soft' : 'secondary',
        data: `data-id="${code}" lang="${code}" aria-pressed="${code === language}"`,
      }),
    ).join('');
    const previous = guideStep > 0
      ? btn(guide.back, 'guide-step', { tone: 'secondary', data: `data-id="${guideStep - 1}"` }) : '';
    const next = last
      ? btn(guide.close, 'close-sheet', { data: 'autofocus' })
      : btn(guide.next, 'guide-step', { data: `data-id="${guideStep + 1}" autofocus` });
    const skip = last ? '' : btn(guide.skip, 'close-sheet', { tone: 'ghost' });
    const stepImage = (GUIDE_PICTURES.length >= 5
      ? [GUIDE_PICTURES[0], GUIDE_PICTURES[1], GUIDE_PICTURES[3], GUIDE_PICTURES[4]][guideStep]
      : GUIDE_PICTURES[guideStep]) || GUIDE_PICTURES[0];
    
    sheet?.classList?.add('guide-modal');
    sheetOpen(guide.title, guide.subtitle,
      `<div class="guide-toolbar">
        <div class="inline" role="group" aria-label="${guide.language}">${languageOptions}</div>
        <span class="chip">${guide.progress(guideStep + 1, guide.steps.length)}</span>
       </div>
       <figure class="guide-illustration">
        <img src="${stepImage}" alt="${safe(step.alt)}" width="968" height="408">
       </figure>
       <div class="guide-description">
        <h3 id="guide-step-title" tabindex="-1">${step.title}</h3>
        <div class="guide-copy">${step.copy}</div>
       </div>`,
      `<div class="guide-actions">${skip}${previous}${next}</div>`,
      language,
    );
  }

  function openGuide() {
    guideStep = 0;
    guideOpen = true;
    showGuide();
  }

  function dismissGuide() {
    guideOpen = false;
    sheet?.classList?.remove('guide-modal');
    sheet.close();
    const invite = pendingGuideInvite;
    pendingGuideInvite = '';
    if (invite) startRoomFlow('join', invite);
  }

  document.addEventListener('cancel', event => {
    if (event.target !== sheet || !guideOpen) return;
    event.preventDefault();
    dismissGuide();
  }, true);

  function moveGuide(value) {
    const step = Number(value);
    if (!Number.isInteger(step) || step < 0 || step >= 4) return;
    guideStep = step;
    showGuide();
    sheet.querySelector('#guide-step-title')?.focus();
  }

  function setGuideLanguage(language) {
    if (language !== 'vi' && language !== 'en') return;
    guideLanguage = language;
    try {
      localStorage.setItem(GUIDE_LANGUAGE_KEY, JSON.stringify(language));
    } catch {
      // Keep the current choice when the browser disallows saving preferences.
    }
    showGuide();
    sheet.querySelector(`[data-act="guide-language"][data-id="${language}"]`)?.focus();
  }

  function showFirstVisitGuide() {
    if (readStorage(GUIDE_KEY) === true) return;
    openGuide();
    try {
      localStorage.setItem(GUIDE_KEY, 'true');
    } catch {
      // The guide remains available even if the browser cannot remember this visit.
    }
  }

  function showJoinedRoomGuide(trip) {
    const key = GUIDE_KEY + ':room:' + rooms.account + ':' + trip.id;
    if (joinedRoomGuides.has(key) || readStorage(key) === true) return;
    joinedRoomGuides.add(key);
    try {
      localStorage.setItem(key, 'true');
    } catch {}
    openGuide();
  }

  function header() {
    const trip = state.trip;
    const newTrip = btn('New trip', 'new-trip', { tone: 'secondary new-trip', symbol: 'plus' });
    const tripsButton = trip?.shared || (!trip && rooms.online) ? '' : trip ? btn('Trips', 'trip-list', { tone: 'ghost' }) : newTrip;
    const avatarButton = trip && !trip.shared
      ? `<button type="button" class="avatar-button" data-act="switch-member" aria-label="Switch demo member">${avatar(member(state.actor) || trip.members[0])}</button>`
      : '';
    const content = trip ? screen() : demoMode
      ? demoLandingScreen()
      : rooms.online ? roomsHome()
      : state.trips.length ? tripsScreen() : empty() + '<div class="stack" style="margin-top:13px">' + fujiPanel() + '</div>';
    return `
      <div class="shell">
        <aside class="sidebar">${brand()}${trip ? navHtml('desktop-nav') : ''}${newTrip}</aside>
        <div class="workspace">
          <header class="header"><div class="header-inner">
            ${brand()}<span class="breadcrumb">${trip ? 'Trips / ' + userText(trip.name) : 'Your trips'}</span>
            <div class="header-actions">
              ${tripsButton}
              ${btn('Guide', 'guide', { tone: 'ghost' })}
              ${siteLanguageSelect()}
              ${roomBell()}
              ${trip?.shared ? '' : '<span class="chip violet header-demo">Demo</span>'}
              ${avatarButton}
            </div>
          </div></header>
          <main class="main" id="main">
            ${storageUnavailable ? '<p class="notice warn">Local storage is unavailable. Changes will be lost when you close or reload this tab.</p>' : ''}
            ${!demoMode && !rooms.online && window.location?.protocol === 'file:' ? '<p class="notice warn">Open the TripVault Rooms launcher for invite links and room codes.</p>' : ''}
            ${trip?.shared ? roomTripToolbar(trip) : ''}
            ${trip?.shared && !rooms.token ? '<p class="notice warn">Your room sign-in expired. ' + btn('Sign in again', 'room-reauthenticate', { tone: 'secondary' }) + '</p>' : ''}
            ${content}
          </main>
        </div>
        ${trip ? navHtml('mobile-nav') : ''}
      </div>`;
  }

  function split() {
    const trip = state.trip;
    const pending = hasPendingBills(trip);
    const quote = trip.reviewQuote;
    const plan = settlementPlan(trip, quote || fx);
    const settled = trip.settled;
    const ended = Date.now() >= roomEndTime(trip);
    const organizer = state.actor === trip.owner;
    const approved = trip.splitApprovals.includes(state.actor);
    const fetching = preparingTrip === trip;

    let reviewActions = '';
    if (!settled && !quote && organizer && (!trip.shared || ended) && canReviewFundedTrip(trip)) {
      reviewActions = btn(fetching ? 'Checking exchange rate…' : trip.shared ? 'Calculate final amounts' : 'Prepare final split', 'prepare-split',
        { disabled: pending || fetching });
    } else if (!settled && quote && trip.shared) {
      if (organizer) reviewActions = btn('Start a new review', 'reopen-split', { tone: 'secondary' });
    } else if (!settled && quote) {
      reviewActions = approved
        ? btn('Cancel approval', 'revoke-split', { tone: 'danger cancel-approval' })
        : btn('Approve split', 'approve-split', { disabled: pending || plan.invalid });
      if (organizer) {
        reviewActions += btn('Settle group', 'settle', { tone: 'secondary', disabled: !canSettle(trip, plan) });
        reviewActions += btn('Reopen split', 'reopen-split', { tone: 'ghost' });
      }
    }
    const fallback = canUseFallback(fallbackReview)
      ? `<div class="notice warn">
          <p>Market rate unavailable. You can retry or prepare the split with this reference.</p>
          <p>${safe(fxLabel(fallbackReview.quote))}</p>
          ${btn('Use fallback rate', 'use-fallback', { tone: 'secondary' })}
        </div>` : '';
    const myShortfall = plan.shortfalls.find(item => item.id === state.actor);
    const topUpAction = quote && !pending && myShortfall
      ? `<div class="top-up-actions">${btn('Top up ' + money(myShortfall.units), 'quick-top-up', {
          data: `data-trip="${safe(trip.id)}" data-member="${safe(state.actor)}" data-revision="${trip.revision}" data-units="${myShortfall.units}"`,
        })}</div>` : '';
    const shortfalls = !trip.shared && !settled && !plan.invalid && plan.shortfalls.length
      ? `<div class="notice warn">
          <p>${quote ? 'Top up the following balances before settlement.' : 'Estimated top-ups. Prepare the final split to lock the amounts.'}</p>
          ${plan.shortfalls.map(item => row(userText(member(item.id).name), money(item.units))).join('')}
          ${topUpAction}
        </div>` : '';
    const transfers = plan.transfers.map(transfer => row(
      safe(member(transfer.from).name) + ' → ' + safe(member(transfer.to).name),
      money(transfer.units), vnd(transfer.vnd) + ' equivalent',
    )).join('');
    const quoteStatus = quote ? (quote.historical ? 'Historical rate' : 'Locked for approval') : 'Estimate';

    return `
      <div class="section-head">
        <div><h1>Final split</h1><p>${userText(trip.name)}</p></div>
        <span class="chip violet">${settled ? 'Settled' : quote ? 'In review' : 'Draft · Pending approvals'}</span>
      </div>
      <div class="stack">
        ${(() => {
          const approved = (trip.bills || []).filter(b => b.status === 'approved');
          return approved.length === 0 ? `
            <div class="card empty-split-card">
              <div style="font-size:28px; margin-bottom:8px;">🧾</div>
              <h3 style="margin:0 0 6px 0; font-size:17px; font-weight:600; color:var(--ink);">Nothing to split yet</h3>
              <p class="subtle" style="margin:0 0 16px 0; font-size:13.5px; line-height:1.5;">
                Add your first bill in the Bills tab. Balances and transfers appear here once bills are approved.
              </p>
              <button type="button" class="btn secondary sm" data-act="navigate" data-view="bills">Go to Bills</button>
            </div>` : '';
        })()}
        ${trip.shared || isAddress(trip.fuji?.address) ? fujiPanel('split') : ''}
        <section class="panel">
          <h2>${trip.shared ? 'Review trip expenses' : isAddress(trip.fuji?.address) ? 'Demo split review' : 'Review the balances'}</h2>
          <p class="subtitle">${trip.shared ? 'Everyone reviews their amount before the organizer makes the group payments.' : trip.splitApprovals.length + ' of ' + trip.members.length + ' approved · Settlement draft (v' + trip.revision + ')'}</p>
          ${reviewActions ? '<div class="inline" style="margin-top:22px">' + reviewActions + '</div>' : ''}
          ${pending ? '<p class="notice warn">' + (trip.shared ? 'Finish open bill reviews before making final payments.'
          : 'Approve all pending bills before the final split.') + '</p>' : ''}
          ${!settled && !quote && !pending && !organizer ? '<p class="notice">The organizer prepares the split and locks the rate for approval.</p>' : ''}
          ${fallback}${shortfalls}
          ${!settled && plan.invalid ? '<p class="notice warn">The current transfers cannot be represented in USDC. Reopen the split and check the rate before settling.</p>' : ''}
          ${!ended ? '<p class="notice">Group payments can start after the trip ends.</p>' : ''}
        </section>
        <section class="panel" style="${(trip.bills || []).filter(b => b.status === 'approved').length === 0 ? 'opacity: 0.55; pointer-events: none;' : ''}">
          <h2>${trip.shared ? 'What each person owes or gets back' : 'Net balances'}</h2>
          ${stats(trip).map(item => row(userText(item.name), vnd(item.net),
            'Paid ' + vnd(item.paid) + ' · Owes ' + vnd(item.owed)
            + (trip.shared ? '' : ' · ' + (trip.splitApprovals.includes(item.id) ? 'Approved' : 'Awaiting approval')))).join('')}
        </section>
        <section class="panel" style="${(trip.bills || []).filter(b => b.status === 'approved').length === 0 ? 'opacity: 0.55; pointer-events: none;' : ''}">
          <h2>${trip.shared ? 'Who pays whom' : 'USDC transfers to settle'}</h2>
          <p class="notice">${formatFxReference(quote || fx)}</p>
          ${transfers || '<p class="empty">No transfers needed yet.</p>'}
          <p class="notice">${trip.shared ? 'These amounts are estimates until the split is published and settled on Fuji.' : 'Demo settlement moves balances within the simulated vault. Each member can claim their balance in Wallet.'}</p>
        </section>
      </div>`;
  }
  function billItem(bill) {
    const payer = member(bill.payer);
    const status = state.trip.shared ? roomBillStatus(bill) : ui(bill.status === 'approved' ? 'Approved' : 'Pending approval');
    const iconName = bill.status === 'approved' ? 'check' : bill.status === 'rejected' ? 'close' : 'bill';
    return `<button type="button" class="bill-row is-${safe(bill.status)}" data-act="bill-detail" data-id="${bill.id}">
      <span class="row-label">
        <span class="bill-badge status-${safe(bill.status)}">${icon(iconName)}</span>
        <span>
          <span class="bill-name">${userText(bill.label)}</span>
          <span class="bill-sub">${ui('Paid by')} ${userText(payer?.name || ui('Unknown'))} · ${ui(bill.participants.length + ' people')}</span>
          <span class="bill-status">${safe(status)}</span>
        </span>
      </span>
      <span class="row-value">${vnd(bill.amount)}</span>
    </button>`;
  }
